detaileddescription.para:
For every GUARD_ALL - FINALLY - E_FINALLY block we create synthetic variables to generate conditional jumps as necessary. As an example, for a block: 
 Loop:
   while (True) {
     try {
         return foo();
     } catch (Exception1 e1) {
         bar1();
         continue;
     } catch (ExceptionN eN) {
         barN();
         break;
     } finally {
         fin();
     }
  }

preformatted.computeroutput:
   Throwable $rethrow  = null;
   boolean   $jump1    = false;
   boolean   $jump2    = false;
   boolean   $doReturn = false;
   R1        $r1;
   try {
       try {
           $r1 = foo();
           $doReturn = true;
           GOTO Fin:
       } catch (Exception1 e1) {
           $rethrow = e1;
           bar1();
           $jump1 = true;
           GOTO Fin:
       } catch (ExceptionN eN) {
           $rethrow = eN;
           barn();
           $jump2 = true;
           GOTO Fin:
       }
   } catch (Throwable $t) {
       $rethrow = $t;
   }

Fin:
   fin();

   if ($rethrow != null) throw $rethrow
   if ($jump1) GOTO Loop.Continue
   if ($jump2) GOTO Loop.Exit
   if ($doReturn) return $r1
